    "cue": "The character of Catiline: gifts named, then the use he made of them.",
    "text": "Lucius Catiline was a man of noble birth, and of eminent mental and personal endowments; but of a vicious and depraved disposition. His delight, from his youth, had been civil commotions, bloodshed, robbery, and sedition; and in such scenes he had spent his early years. His constitution could endure hunger, want of sleep, and cold, to a degree surpassing belief. His mind was daring, subtle, and versatile, capable of pretending or dissembling whatever he wished. He was covetous of other men's property, and prodigal of his own. He had abundance of eloquence, though but little wisdom. His insatiable ambition was always pursuing objects extravagant, romantic, and unattainable. Since the time of Sylla's dictatorship, a strong desire of seizing the government possessed him, nor did he at all care, provided that he secured power for himself, by what means he might arrive at it.",
