    "text": "A few days after, without the knowledge of Collatinus, Sextus came to Collatia with one attendant only; where, being kindly received by them, as not being aware of his intention, after he had been conducted after supper into the guests' chamber, burning with passion, when every thing around seemed sufficiently secure, and all fast asleep, he comes to Lucretia, as she lay asleep, with a naked sword, and with his left hand pressing down the woman's breast, he says, \"Be silent, Lucretia; I am Sextus Tarquin; I have a sword in my hand; you shall die, if you utter a word.\" When awaking terrified from sleep, the woman beheld no aid, impending death nigh at hand; then Tarquin acknowledged his passion, entreated, mixed threats with entreaties, tried the female's mind in every possible way. When he saw her inflexible, and that she was not moved even by the terror of death, he added to terror the threat of dishonour; he says that he will lay a murdered slave naked by her side when dead, so that she may be said to have been slain in infamous adultery.",
