    "cue": "Athenian friendship as a gift, not a debt received.",
    "text": "In generosity we are equally singular, acquiring our friends by conferring, not by receiving, favours. Yet, of course, the doer of the favour is the firmer friend of the two, in order by continued kindness to keep the recipient in his debt; while the debtor feels less keenly from the very consciousness that the return he makes will be a payment, not a free gift. And it is only the Athenians, who, fearless of consequences, confer their benefits not from calculations of expediency, but in the confidence of liberality. “In short, I say that as a city we are the school of Hellas, while I doubt if the world can produce a man who, where he has only himself to depend upon, is equal to so many emergencies, and graced by so happy a versatility, as the Athenian.",
