    "text": "To sum up as shortly as possible, embracing both general and particular considerations, let this show you the folly of sacrificing us. Remember that there are but three considerable naval powers in Hellas—Athens, Corcyra, and Corinth—and that if you allow two of these three to become one, and Corinth to secure us for herself, you will have to hold the sea against the united fleets of Corcyra and Peloponnese. But if you receive us, you will have our ships to reinforce you in the struggle.” Such were the words of the Corcyraeans. After they had finished, the Corinthians spoke as follows: “These Corcyraeans in the speech we have just heard do not confine themselves to the question of their reception into your alliance.",
