    "cue": "Sarcasm: the boy who never touched the javelin thrust it through his own ribs.",
    "text": "He has the audacity and the insolence to claim that his son, who both threw and killed, did not wound or kill; and he asserts that my son, who did not touch the javelin and never even thought of throwing it, missed the whole earth and everyone else on it and thrust the javelin through his own ribs. I think I could make a more convincing case for intentional homicide than this man can when he asserts that the young man neither threw nor killed.",
