    "cue": "The theft of pears: he loved the fault, not the fruit.",
    "text": "9. Theft is punished by Thy law, O Lord, and the law written in the hearts of men, which iniquity itself effaces not. For what thief will abide a thief? not even a rich thief, one stealing through want. Yet I lusted to thieve, and did it, compelled by no hunger, nor poverty, but through a cloyedness of well-doing, and a pamperedness of iniquity. For I stole that, of which I had enough, and much better. Nor cared I to enjoy what I stole, but joyed in the theft and sin itself. A pear tree there was near our vineyard, laden with fruit, tempting neither for colour nor taste. To shake and rob this, some lewd young fellows of us went, late one night (having according to our pestilent custom prolonged our sports in the streets till then), and took huge loads, not for our eating, but to fling to the very hogs, having only tasted them. And this, but to do what we liked only, because it was misliked. Behold my heart, O God, behold my heart, which Thou hadst pity upon in the bottom of the bottomless pit. Now, behold, let my heart tell Thee what it sought there, that I should be gratuitously evil, having no temptation to ill, but the ill itself. It was foul, and I loved it; I loved to perish, I loved mine own fault, not that for which I was faulty, but my fault itself. Foul soul, falling from Thy firmament to utter destruction; not seeking aught through the shame, but the shame itself!",
